function deplacer() {
  if (!gameOver && !enPause && !clearing) {
    if (canFit(curPiece, curRot, curX + moveDx, curY)) {
      curX += moveDx;
      game.playSound('deplacement', 1, 1);
      mettreAJourAffichage();
    }
  }
}

function tourner() {
  if (!gameOver && !enPause && !clearing) {

                  const nextRot = (curRot + rotDir + 4) % 4;
                  const kicks = [[0, 0], [-1, 0], [1, 0], [-2, 0], [2, 0], [0, -1]];
                  let turned = false;
                  for (let i = 0; i < kicks.length; i++) {
                    const kx = kicks[i][0], ky = kicks[i][1];
                    if (canFit(curPiece, nextRot, curX + kx, curY + ky)) {
                      curRot = nextRot;
                      curX += kx;
                      curY += ky;
                      turned = true;
                      break;
                    }
                  }
                ;
    if (turned) {
      game.playSound('rotation', 1, 1);
      mettreAJourAffichage();
    }
  }
}

